function GlobalLoader({
  mode = "fullscreen",
  message,
  phase,
  progress,
  error = null,
  onRetry = null,
  title = "সমাজতান্ত্রিক ছাত্র ফ্রন্ট",
  subtitle = "ময়মনসিংহ জেলা শাখা",
  className = ""
}) {
  const [currentPhaseIndex, setCurrentPhaseIndex] = Q.useState(0);
  const defaultPhases = [
    "অনলাইন ডাটাবেজ লোড হচ্ছে",
    "নিরাপদ সংযোগ স্থাপন করা হচ্ছে",
    "তথ্য প্রস্তুত করা হচ্ছে",
    "সিস্টেম প্রস্তুত করা হচ্ছে"
  ];

  Q.useEffect(() => {
    if (phase || error) return;
    const interval = setInterval(() => {
      setCurrentPhaseIndex(prev => (prev + 1) % defaultPhases.length);
    }, 2200);
    return () => clearInterval(interval);
  }, [phase, error]);

  const activeStatusText = error 
    ? (typeof error === "string" ? error : "ডাটাবেজ সংযোগে সমস্যা দেখা দিয়েছে।")
    : (message || phase || defaultPhases[currentPhaseIndex]);

  const isCompact = mode === "compact";
  const isInline = mode === "inline";
  const isFullscreen = mode === "fullscreen" || mode === "overlay";

  const emblemDimension = isCompact ? "w-12 h-12" : isInline ? "w-16 h-16" : "w-20 h-20 sm:w-22 sm:h-22";
  const ambientDimension = isCompact ? "w-20 h-20" : isInline ? "w-28 h-28" : "w-36 h-36 sm:w-40 sm:h-40";

  const errorIcon = i.jsxs("svg", {
    className: "w-6 h-6 text-rose-600 dark:text-rose-500 shrink-0",
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: "2",
    strokeLinecap: "round",
    strokeLinejoin: "round",
    children: [
      i.jsx("path", { d: "m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z" }),
      i.jsx("line", { x1: "12", y1: "9", x2: "12", y2: "13" }),
      i.jsx("line", { x1: "12", y1: "17", x2: "12.01", y2: "17" })
    ]
  });

  const retryIcon = i.jsxs("svg", {
    className: "w-3.5 h-3.5 mr-1.5 inline-block",
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: "2",
    strokeLinecap: "round",
    strokeLinejoin: "round",
    children: [
      i.jsx("path", { d: "M21.5 2v6h-6" }),
      i.jsx("path", { d: "M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.67" })
    ]
  });

  const containerClasses = isFullscreen
    ? "min-h-[70vh] sm:min-h-[78vh] w-full flex flex-col items-center justify-center p-6 sm:p-10 select-none " + className
    : isInline
      ? "py-12 px-4 w-full flex flex-col items-center justify-center select-none " + className
      : "py-6 px-4 w-full flex flex-col items-center justify-center select-none " + className;

  if (error) {
    return i.jsxs("div", {
      className: containerClasses,
      role: "alert",
      children: [
        i.jsxs("div", {
          className: "max-w-md w-full mx-auto p-6 sm:p-8 rounded-2xl bg-white dark:bg-zinc-900 border border-rose-200/80 dark:border-rose-950/60 shadow-lg shadow-rose-950/5 dark:shadow-black/40 text-center space-y-4 font-sans relative overflow-hidden",
          children: [
            i.jsx("div", {
              className: "w-12 h-12 mx-auto rounded-full bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-900/50 flex items-center justify-center",
              children: errorIcon
            }),
            i.jsxs("div", {
              className: "space-y-1.5",
              children: [
                i.jsx("h3", {
                  className: "text-base sm:text-lg font-bold text-zinc-900 dark:text-zinc-100 font-serif",
                  children: "ডাটাবেজ সংযোগ ত্রুটি"
                }),
                i.jsx("p", {
                  className: "text-xs sm:text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed font-sans",
                  children: typeof error === "string" ? error : "ক্লাউড ডাটাবেজের সাথে সংযোগ স্থাপন করা সম্ভব হয়নি। অনুগ্রহ করে ইন্টারনেট সংযোগ চেক করুন।"
                })
              ]
            }),
            onRetry && i.jsxs("button", {
              onClick: onRetry,
              className: "inline-flex items-center justify-center px-5 py-2.5 bg-rose-600 hover:bg-rose-700 active:scale-95 text-white font-medium rounded-xl text-xs sm:text-sm transition-all duration-200 shadow-md shadow-rose-600/20 cursor-pointer",
              children: [
                retryIcon,
                i.jsx("span", { children: "পুনরায় চেষ্টা করুন" })
              ]
            })
          ]
        })
      ]
    });
  }

  return i.jsxs("div", {
    className: containerClasses,
    role: "status",
    "aria-live": "polite",
    "aria-busy": "true",
    children: [
      i.jsx("div", {
        className: "ssf-logo-wrapper mb-4 sm:mb-5",
        children: i.jsxs("div", {
          className: "ssf-logo-floater relative",
          children: [
            i.jsx("div", { className: ambientDimension + " ssf-logo-ambient" }),
            i.jsx("div", {
              className: emblemDimension + " ssf-logo-emblem flex items-center justify-center relative",
              children: i.jsx("img", {
                src: "https://i.ibb.co.com/F4MKM3R2/20260527-055637.png",
                alt: "সমাজতান্ত্রিক ছাত্র ফ্রন্ট",
                referrerPolicy: "no-referrer",
                className: "w-full h-full object-contain pointer-events-none select-none rounded-full"
              })
            })
          ]
        })
      }),
      !isCompact && i.jsxs("div", {
        className: "text-center mb-3 sm:mb-4 space-y-0.5",
        children: [
          i.jsx("h1", {
            className: "text-base sm:text-lg font-bold text-zinc-900 dark:text-zinc-100 tracking-normal font-serif",
            children: title
          }),
          subtitle && i.jsx("p", {
            className: "text-[11px] sm:text-xs text-rose-600 dark:text-rose-400 font-semibold tracking-wider",
            children: subtitle
          })
        ]
      }),
      i.jsxs("div", {
        key: activeStatusText,
        className: "ssf-status-text flex items-center justify-center gap-1.5 text-xs sm:text-[13px] text-zinc-600 dark:text-zinc-300 font-sans font-medium mb-3.5",
        children: [
          i.jsx("span", { children: activeStatusText }),
          i.jsxs("span", {
            className: "font-bold text-rose-600 dark:text-rose-400 tracking-wider inline-block",
            children: [
              i.jsx("span", { className: "ssf-dot-1", children: "." }),
              i.jsx("span", { className: "ssf-dot-2", children: "." }),
              i.jsx("span", { className: "ssf-dot-3", children: "." })
            ]
          })
        ]
      }),
      i.jsx("div", {
        className: "ssf-progress-track",
        children: typeof progress === "number"
          ? i.jsx("div", {
              className: "h-full bg-rose-600 dark:bg-rose-500 rounded-full transition-all duration-300",
              style: { width: `${Math.min(100, Math.max(0, progress))}%` }
            })
          : i.jsx("div", {
              className: "ssf-progress-bar-active"
            })
      })
    ]
  });
}
